changeSet.sql:
CREATE UNIQUE INDEX IF NOT EXISTS uk_tenant_feature_active
ON UNIPOST_TENANT_FEATURES (tenant_id, feature_key);

CREATE INDEX IF NOT EXISTS idx_tenant_billing_status
ON UNIPOST_TENANT_BILLING (tenant_id, status);

-- 4. Enable Row-Level Security (RLS) on Billing & Features
ALTER TABLE UNIPOST_TENANT_BILLING ENABLE ROW LEVEL SECURITY;
ALTER TABLE UNIPOST_TENANT_FEATURES ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS tenant_isolation_billing ON UNIPOST_TENANT_BILLING;
CREATE POLICY tenant_isolation_billing ON UNIPOST_TENANT_BILLING
    FOR ALL
    USING (
        tenant_id = NULLIF(current_setting('app.current_tenant_id', true), '')
        OR tenant_id = 'SYSTEM'
    )
    WITH CHECK (
        tenant_id = NULLIF(current_setting('app.current_tenant_id', true), '')
        AND tenant_id != 'SYSTEM'
    );

DROP POLICY IF EXISTS tenant_isolation_features ON UNIPOST_TENANT_FEATURES;
CREATE POLICY tenant_isolation_features ON UNIPOST_TENANT_FEATURES
    FOR ALL
    USING (
        tenant_id = NULLIF(current_setting('app.current_tenant_id', true), '')
        OR tenant_id = 'SYSTEM'
    )
    WITH CHECK (
        tenant_id = NULLIF(current_setting('app.current_tenant_id', true), '')
        AND tenant_id != 'SYSTEM'
    );
